package com.saumyasolar.service;
import com.saumyasolar.domain.*;import com.saumyasolar.repo.*;import com.saumyasolar.security.Principal;import jakarta.transaction.Transactional;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;import java.io.IOException;import java.nio.file.*;import java.time.Instant;import java.util.*;
@Service
public class WarrantyClaimAttachmentService {
 private static final long MAX_SIZE=10L*1024*1024;private final Path root;private final WarrantyClaimAttachmentRepository attachments;private final WarrantyClaimRepository claims;private final CustomerProfileRepository customers;
 public WarrantyClaimAttachmentService(@Value("${app.warranty.attachment-location:./data/private-warranty-attachments}") String location,WarrantyClaimAttachmentRepository attachments,WarrantyClaimRepository claims,CustomerProfileRepository customers){this.root=Path.of(location).toAbsolutePath().normalize();this.attachments=attachments;this.claims=claims;this.customers=customers;}
 private WarrantyClaim authorize(UUID claimId,Principal p){if(p==null||p.tenantId()==null)throw new ResponseStatusException(HttpStatus.FORBIDDEN);WarrantyClaim c=claims.findByIdAndTenantId(claimId,p.tenantId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Warranty claim not found"));if("CUSTOMER".equals(p.accountType())){CustomerProfile cp=customers.findByTenantIdAndUserId(p.tenantId(),p.userId()).filter(CustomerProfile::isActive).orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN));if(!cp.getId().equals(c.getCustomerId()))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Warranty claim not found");return c;}if(!"VENDOR".equals(p.accountType())||p.permissions()==null||!p.permissions().contains("SURVEY_MANAGE")||p.roles()==null||p.roles().stream().noneMatch(r->Set.of("VENDOR_ADMIN","OPERATIONS_MANAGER","SERVICE_MANAGER").contains(r)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Warranty claim access denied");return c;}
 @Transactional public WarrantyClaimAttachment upload(UUID claimId,MultipartFile file,Principal p){authorize(claimId,p);if(file==null||file.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose claim evidence");if(file.getSize()>MAX_SIZE)throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE,"Claim evidence must be 10 MB or smaller");String type=file.getContentType()==null?"":file.getContentType().toLowerCase(Locale.ROOT);if(!Set.of("image/jpeg","image/png","image/webp","application/pdf").contains(type))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Only JPEG, PNG, WebP and PDF claim evidence is supported");
 try{byte[] bytes=file.getBytes();if(!valid(bytes,type))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"File signature does not match content type");String ext=switch(type){case "image/jpeg"->".jpg";case "image/png"->".png";case "image/webp"->".webp";default->".pdf";};String key=UUID.randomUUID()+ext;Files.createDirectories(root);Path target=root.resolve(key).normalize();if(!target.startsWith(root))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid evidence path");Files.write(target,bytes,StandardOpenOption.CREATE_NEW);try{WarrantyClaimAttachment a=new WarrantyClaimAttachment();a.setId(UUID.randomUUID());a.setTenantId(p.tenantId());a.setClaimId(claimId);a.setOriginalName(safeName(file.getOriginalFilename()));a.setStorageKey(key);a.setContentType(type);a.setSizeBytes(bytes.length);a.setUploadedBy(p.userId());a.setCreatedAt(Instant.now());return attachments.save(a);}catch(RuntimeException ex){Files.deleteIfExists(target);throw ex;}}
 catch(IOException ex){throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR,"Unable to store claim evidence",ex);}}
 public List<WarrantyClaimAttachment> list(UUID claimId,Principal p){authorize(claimId,p);return attachments.findByTenantIdAndClaimIdOrderByCreatedAtAsc(p.tenantId(),claimId);}
 public Download download(UUID claimId,UUID attachmentId,Principal p){authorize(claimId,p);WarrantyClaimAttachment a=attachments.findByIdAndTenantIdAndClaimId(attachmentId,p.tenantId(),claimId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Claim evidence not found"));try{Path file=root.resolve(a.getStorageKey()).normalize();if(!file.startsWith(root)||!Files.isRegularFile(file))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Claim evidence file not found");return new Download(a,Files.readAllBytes(file));}catch(IOException ex){throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR,"Unable to read claim evidence",ex);}}
 private boolean valid(byte[] b,String type){if(type.equals("application/pdf"))return b.length>=5&&b[0]=='%'&&b[1]=='P'&&b[2]=='D'&&b[3]=='F'&&b[4]=='-';if(type.equals("image/jpeg"))return b.length>=3&&(b[0]&255)==255&&(b[1]&255)==216&&(b[2]&255)==255;if(type.equals("image/png"))return b.length>=8&&(b[0]&255)==137&&b[1]=='P'&&b[2]=='N'&&b[3]=='G';return b.length>=12&&b[0]=='R'&&b[1]=='I'&&b[2]=='F'&&b[3]=='F'&&b[8]=='W'&&b[9]=='E'&&b[10]=='B'&&b[11]=='P';}
 private String safeName(String value){if(value==null||value.isBlank())return "claim-evidence";String normalized=value.replace("\\","/");String name=normalized.substring(normalized.lastIndexOf('/')+1).replaceAll("[^A-Za-z0-9._-]","_");return name.length()>200?name.substring(name.length()-200):name;}
 public record Download(WarrantyClaimAttachment attachment,byte[] content){}
}
